    files = [
      {path: PREFIX + 'FIRST_PILOT.md', mode: '100644', type: 'blob', content: d.report},
      {path: PREFIX + 'FIRST_PILOT_RECEIPT.json', mode: '100644', type: 'blob', content: JSON.stringify(d.receipt, null, 2) + '\n'}];
