"""Repository research state reducer and bounded, allowlisted stage dispatcher."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import signal
import time
from datetime import datetime,timezone
try:
    from .autonomy.execution_policy import digest, validate as validate_execution
except ImportError:  # Direct CLI: python infra/research_pipeline.py.
    from autonomy.execution_policy import digest, validate as validate_execution

REPO=Path(__file__).resolve().parents[1]
PKG=REPO/'analysis/CCC_BBN_NETWORK_20261114/pipeline'
IMPLEMENTATIONS={'s1_fullnet':REPO/'analysis/CCC_BBN_NETWORK_20261114/s1_fullnet/launch.py', 's_eta':REPO/'analysis/CCC_BBN_NETWORK_20261114/s_eta/launch.py'}

def read(path):return json.loads(Path(path).read_text())
def write(path,value):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def git(*args):return subprocess.check_output(['git','-C',str(REPO),*args],text=True).strip()
def safe(path):
    p=(REPO/path).resolve()
    if not p.is_relative_to(REPO):raise ValueError('Path outside repository')
    return p
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def contract_complete(value,stage):
    engineering=value.get('status')=='ENGINEERING_PASS'
    if ('status' not in value and stage['kind']=='import'
            and stage['status_field']=='engineering_status'):
        engineering=value.get('engineering_status')=='PASS'
    return engineering and value.get(stage['status_field'])==stage['expected_status']

def validate_definition(plan):
    ids=[s['id'] for s in plan['stages']]
    if len(ids)!=len(set(ids)):raise ValueError('Duplicate stage')
    nodes={s['id']:s for s in plan['stages']};active=set();done=set()
    def walk(key):
        if key not in nodes:raise ValueError('Unknown dependency '+key)
        if key in active:raise ValueError('Dependency cycle')
        if key in done:return
        active.add(key)
        for dep in nodes[key]['depends']:walk(dep)
        active.remove(key);done.add(key)
    for key in ids:walk(key)
    for s in plan['stages']:
        if s['kind']=='execute' and s.get('implementation') not in IMPLEMENTATIONS:raise ValueError('Unreviewed implementation')
        if s['kind'] in ('contract','theory','separate_line') and s.get('automatic'):raise ValueError('Cannot auto-run a missing scientific contract')
    return nodes

def verify_import(stage):
    for key in ('summary','manifest'):
        ref=stage[key]
        if sha(safe(ref['path']))!=ref['sha256']:raise ValueError('Pinned '+key+' differs')
    manifest=safe(stage['manifest']['path']);root=manifest.parent
    document=read(manifest)
    entries=document.get('files',document)
    for rel,entry in entries.items():
        expected=entry['sha256'] if isinstance(entry,dict) else entry
        if not isinstance(expected,str) or len(expected)!=64:raise ValueError('Invalid artifact digest')
        path=(root/rel).resolve()
        if not path.is_relative_to(root) or sha(path)!=expected:raise ValueError('Input artifact changed: '+rel)
    return read(safe(stage['summary']['path']))

def evaluate(plan,request):
    nodes=validate_definition(plan);state={}
    def visit(key):
        if key in state:return state[key]
        s=nodes[key];deps={d:visit(d)['status'] for d in s['depends']}
        if s['kind']=='import':
            try:
                value=verify_import(s);ok=contract_complete(value,s)
                row={'status':'COMPLETE' if ok else 'REVIEW_REQUIRED','evidence':s['summary']['path'],'numerical_status':value.get(s['status_field'])}
            except (ValueError,OSError,KeyError) as exc:row={'status':'INTEGRITY_ERROR','error':str(exc)}
        elif s['kind']=='execute':
            result=safe(s['result'])
            if result.exists():
                value=read(result)
                try:
                    manifest=result.parent/'ARTIFACTS.json'
                    receipt=read(result.parent/'ARTIFACTS_SHA256.json')
                    if sha(manifest)!=receipt['sha256']:raise ValueError('Result manifest changed')
                    entries=read(manifest)['files']
                    if result.name not in entries:raise ValueError('Summary absent from artifact manifest')
                    for rel,h in entries.items():
                        path=(result.parent/rel).resolve()
                        if not path.is_relative_to(result.parent) or sha(path)!=h['sha256']:raise ValueError('Result artifact changed')
                    ok=contract_complete(value,s) and all(v=='COMPLETE' for v in deps.values())
                    row={'status':'COMPLETE' if ok else 'REVIEW_REQUIRED','evidence':s['result'],'numerical_status':value.get(s['status_field']),'engineering_status':value.get('status'),'reused':True}
                except (ValueError,OSError,KeyError) as exc:row={'status':'INTEGRITY_ERROR','error':str(exc)}
            elif (result.parent/'LEDGER.jsonl').exists():row={'status':'INTERRUPTED_OR_RUNNING','automatic_retry':False}
            elif any(v!='COMPLETE' for v in deps.values()):row={'status':'WAITING_DEPENDENCY'}
            elif key in request['stages'] and request['execution_enabled']:row={'status':'READY'}
            else:row={'status':'NOT_REQUESTED'}
        else:
            row={'status':'OPEN_THEORY' if s['kind']=='theory' else 'CONTRACT_REQUIRED','missing':s.get('missing',[]),'next_action':s['next']}
            if any(v!='COMPLETE' for v in deps.values()):row['waiting_dependencies']=[d for d,v in deps.items() if v!='COMPLETE']
        row['dependencies']=deps;state[key]=row;return row
    for key in nodes:visit(key)
    return {'schema':'vm-lab-pipeline-state-v1','pipeline':plan['id'],'request':request['id'],'observed_utc':datetime.now(timezone.utc).isoformat(),'source_commit':git('rev-parse','HEAD'),'stages':state,'scientific_acceptance':False,'r_c_l_u_changed':False}

def render(state):
    lines=['# CCC–BBN: состояние общего пайплайна','',f"Запрос: `{state['request']}`. Снимок: {state['observed_utc']}.",'','| Этап | Состояние | Следующее действие / свидетельство |','|---|---|---|']
    for key,row in state['stages'].items():
        detail=row.get('evidence') or row.get('next_action') or row.get('error') or ''
        lines.append(f"| {key} | {row['status']} | {detail} |")
    lines+=['','COMPLETE означает проверенное завершение указанного вычислительного контракта. Научная приёмка и статусы R/C/L/U остаются отдельными. S2/BH1 не блокируют независимые готовые этапы.']
    return '\n'.join(lines)+'\n'

def save_state(state):
    root=PKG/'results'/state['request'];write(root/'STATE.json',state)
    (root/'REPORT.md').write_text(render(state))
    write(PKG/'CURRENT.json',{'request':state['request'],'state':str((root/'STATE.json').relative_to(REPO)),'report':str((root/'REPORT.md').relative_to(REPO)),'observed_utc':state['observed_utc'],'scientific_acceptance':False})
    return root

def publish(root,branch):
    if git('branch','--show-current')!=branch:raise ValueError('Wrong publication branch')
    allowed=[str(root.relative_to(REPO)),str((PKG/'CURRENT.json').relative_to(REPO))]
    git('add','--',*allowed)
    staged=git('diff','--cached','--name-only').splitlines()
    if any(p!=allowed[1] and not p.startswith(allowed[0]+'/') for p in staged):raise ValueError('Unexpected staged file')
    if staged:git('commit','-m','Update research pipeline state and next-stage requirements');git('push','origin','HEAD:refs/heads/'+branch)
    if git('ls-remote','origin','refs/heads/'+branch).split()[0]!=git('rev-parse','HEAD'):raise ValueError('Publication not confirmed')

def stage_checkpoint(stage,phase):
    """Called directly by the executing stage; no workflow-event chaining needed."""
    plan=read(PKG/'PIPELINE.json');request=read(PKG/'RUN_REQUEST.json')
    if stage not in request['stages'] or os.environ.get('GITHUB_ACTIONS')!='true':raise ValueError('Unexpected stage checkpoint')
    state=evaluate(plan,request)
    state['stages'][stage].update(status='RUNNING',phase=phase,workflow_url='https://github.com/IgorSabirov/vm-lab/actions/runs/'+os.environ['GITHUB_RUN_ID'])
    root=save_state(state);publish(root,plan['branch'])

def execution_admission(request):
    """A hosted controller cannot execute a VM/local plan or bypass admission."""
    receipt=read(Path(os.environ['RUNNER_TEMP'])/'autonomy-budget.json')
    execution=read(safe(request['execution_plan']))
    report=validate_execution(execution,read(REPO/'infra/autonomy/CONTROL.json')['limits'],root=REPO)
    if (not receipt.get('execute') or report['executor']!='github_actions'
            or receipt.get('plan_sha256')!=digest(execution)
            or receipt.get('reservation',{}).get('id')!=request['id']
            or receipt['reservation'].get('workflow_run_id')!=int(os.environ['GITHUB_RUN_ID'])
            or len(execution['sections'])!=1):
        raise ValueError('Missing/mismatched single-section Actions admission')
    return execution

def bounded_process(argv,seconds):
    # Kill the entire process group on a hard deadline, not just its launcher.
    with subprocess.Popen(argv,cwd=REPO,start_new_session=True) as process:
        try:return process.wait(timeout=seconds)
        except subprocess.TimeoutExpired:
            os.killpg(process.pid,signal.SIGKILL)
            process.wait()
            raise ValueError('Section compute budget exhausted; no automatic retry')

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--execute',action='store_true');ap.add_argument('--upstream');ap.add_argument('--output',type=Path);a=ap.parse_args()
    plan=read(PKG/'PIPELINE.json');req=read(PKG/'RUN_REQUEST.json');nodes=validate_definition(plan)
    if any(k not in nodes or nodes[k]['kind']!='execute' for k in req['stages']):raise ValueError('Unknown/non-executable requested stage')
    state=evaluate(plan,req)
    if not a.execute:
        if a.output:write(a.output,state)
        print(json.dumps({k:v['status'] for k,v in state['stages'].items()}));return 0
    if not a.upstream:raise ValueError('Pinned upstream checkout required')
    if os.environ.get('GITHUB_REPOSITORY')!='IgorSabirov/vm-lab' or os.environ.get('GITHUB_REF')!='refs/heads/'+plan['branch'] or os.environ.get('GITHUB_RUN_ATTEMPT')!='1':raise ValueError('Wrong executor or forbidden retry')
    execution=execution_admission(req)
    deadline=time.monotonic()+execution['sections'][0]['compute_seconds']
    exit_code=0
    try:
        for key in req['stages']:
            status=state['stages'][key]['status']
            if status=='COMPLETE':continue
            if status!='READY':raise ValueError(key+' cannot start: '+status+'; no automatic repeat')
            entry=IMPLEMENTATIONS[nodes[key]['implementation']]
            remaining=deadline-time.monotonic()
            if remaining<=0:raise ValueError('Section compute budget exhausted')
            returncode=bounded_process([sys.executable,str(entry),'--upstream',str(Path(a.upstream).resolve())],remaining)
            state=evaluate(plan,req)
            if returncode or state['stages'][key]['status']!='COMPLETE':exit_code=1;break
    except Exception as exc:
        exit_code=1;state=evaluate(plan,req);state['controller_error']=str(exc)
    finally:
        root=save_state(state);publish(root,plan['branch'])
    return exit_code

if __name__=='__main__':raise SystemExit(main())

"""Shared package accounting and leased admission, before scientific execution."""
from __future__ import annotations
import base64
from datetime import datetime, timezone, timedelta
import json
import os
from pathlib import Path
import subprocess
import urllib.error
import urllib.parse
import urllib.request
try:
    from .execution_policy import digest, validate
except ImportError:  # Direct CLI invocation from repository root.
    from execution_policy import digest, validate

REPOSITORY = 'IgorSabirov/vm-lab'
LEDGER_BRANCH = 'science/autonomous-research-20261114'
LEDGER_PATH = 'infra/autonomy/LEDGER.json'
REQUEST_PATH = 'analysis/CCC_BBN_NETWORK_20261114/pipeline/RUN_REQUEST.json'
ACTIVE = {'RESERVED', 'SUBMITTED', 'QUEUED', 'RUNNING', 'UNKNOWN'}


def moment(value):
    result = datetime.fromisoformat(value.replace('Z', '+00:00'))
    if result.tzinfo is None:
        raise ValueError('Ledger timestamps must include timezone')
    return result


def package_records(ledger, runs, now, current_run_id=None):
    """Union local/VM/Actions packages; run IDs are evidence, not package IDs."""
    records = {}; mapped = set()
    for row in ledger['packages']:
        key = row['id']
        if key in records:
            raise ValueError('Duplicate package identity in ledger')
        moment(row['started_utc']); records[key] = dict(row)
        ids = list(row.get('workflow_run_ids', []))
        if row.get('workflow_run_id') is not None:
            ids.append(row['workflow_run_id'])
        for run_id in set(ids):
            if run_id in mapped:
                raise ValueError('Workflow run belongs to two packages')
            mapped.add(run_id)
    for run in runs:
        if (run['id'] in mapped or run['id'] == current_run_id
                or not run.get('head_branch', '').startswith('science/autonomous-')):
            continue
        records['unmapped_actions_' + str(run['id'])] = {
            'id': 'unmapped_actions_' + str(run['id']), 'started_utc': run['created_at'],
            'status': 'RUNNING' if run['status'] != 'completed' else 'UNMAPPED_TERMINAL',
            'workflow_run_id': run['id'], 'executor': 'github_actions'}
    if any(moment(r['started_utc']) > now for r in records.values()):
        raise ValueError('Ledger timestamp is in the future')
    return records


def decision(ledger, runs, candidate, now, limits, current_run_id=None):
    records = package_records(ledger, runs, now, current_run_id)
    if candidate['id'] in records:
        return {'admitted': False, 'reason': 'ALREADY_REGISTERED_NO_RETRY'}
    if any(r.get('status') in ACTIVE for r in records.values()):
        return {'admitted': False, 'reason': 'ACTIVE_PACKAGE'}
    # Half-open rolling window: an entry leaves exactly 24 h after admission.
    recent = {k: r for k, r in records.items() if moment(r['started_utc']) > now - timedelta(hours=24)}
    cap = limits['new_packages_per_rolling_24h']; admitted = len(recent) < cap
    result = {'admitted': admitted, 'reason': 'ADMITTED' if admitted else 'BUDGET_WAIT',
              'packages_last_24h': sorted(recent), 'limit': cap}
    if not admitted:
        starts = sorted(moment(r['started_utc']) for r in recent.values())
        result['not_before_utc'] = (starts[len(starts) - cap] + timedelta(hours=24)).isoformat()
    return result


def reserve(read_ledger, write_ledger, runs, candidate, now, limits, current_run_id=None):
    """CAS is shared by every executor. A conflict requires a fresh decision."""
    for _ in range(3):
        ledger, expected_blob = read_ledger()
        result = decision(ledger, runs, candidate, now, limits, current_run_id)
        if not result['admitted']:
            return result
        updated = {**ledger, 'packages': ledger['packages'] + [candidate]}
        if write_ledger(updated, expected_blob):
            return {**result, 'reservation': candidate}
    raise ValueError('Concurrent ledger updates; no package admitted')


def api(path, data=None):
    headers = {'Accept': 'application/vnd.github+json', 'Authorization': 'Bearer ' + os.environ['GH_TOKEN']}
    request = urllib.request.Request('https://api.github.com/repos/' + REPOSITORY + '/' + path,
                                     headers=headers, data=None if data is None else json.dumps(data).encode(),
                                     method='GET' if data is None else 'PUT')
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.load(response)


def read_ledger():
    data = api('contents/' + LEDGER_PATH + '?ref=' + urllib.parse.quote(LEDGER_BRANCH, safe=''))
    return json.loads(base64.b64decode(data['content'])), data['sha']


def write_ledger(value, expected_blob):
    try:
        api('contents/' + LEDGER_PATH, {
            'branch': LEDGER_BRANCH, 'sha': expected_blob,
            'message': 'Update autonomous package reservation and evidence',
            'content': base64.b64encode((json.dumps(value, indent=2) + '\n').encode()).decode()})
        return True
    except urllib.error.HTTPError as exc:
        if exc.code == 409:
            return False
        # An uncertain write never causes a new submission automatically.
        raise


def actions_runs(now):
    runs = []
    for page in range(1, 11):
        batch = api('actions/workflows/research-pipeline.yml/runs?per_page=100&page=' + str(page))['workflow_runs']
        runs.extend(batch)
        if len(batch) < 100 or moment(batch[-1]['created_at']) < now - timedelta(hours=24):
            return runs
    raise ValueError('Cannot establish 24-hour Actions history')


def source_check(plan, path, request):
    if plan['package_id'] != request['id'] or plan['publication_branch'] != os.environ['GITHUB_REF_NAME']:
        raise ValueError('Package/branch does not match request')
    subprocess.run(['git', 'merge-base', '--is-ancestor', plan['source_commit'], 'HEAD'], check=True)
    changed = subprocess.check_output(['git', 'diff', '--name-only', plan['source_commit'], 'HEAD'], text=True).splitlines()
    if set(changed) - {path, REQUEST_PATH}:
        raise ValueError('Source changed after freeze; only request/plan publication may follow')


def receipt(value):
    Path(os.environ['RUNNER_TEMP'], 'autonomy-budget.json').write_text(json.dumps(value, indent=2) + '\n')
    if os.environ.get('GITHUB_OUTPUT'):
        with open(os.environ['GITHUB_OUTPUT'], 'a') as output:
            output.write('execute=' + str(value.get('execute', False)).lower() + '\n')
    print(json.dumps(value))


def main():
    if os.environ['GITHUB_REPOSITORY'] != REPOSITORY or os.environ['GITHUB_RUN_ATTEMPT'] != '1':
        raise ValueError('Wrong repository or forbidden retry')
    if not os.environ['GITHUB_REF_NAME'].startswith('science/autonomous-'):
        raise ValueError('Wrong autonomous branch')
    request = json.loads(Path(REQUEST_PATH).read_text())
    if not request.get('execution_enabled'):
        receipt({'execute': False, 'reason': 'EXECUTION_DISABLED', 'scientific_acceptance': False})
        return
    control = json.loads(Path('infra/autonomy/CONTROL.json').read_text())
    path = request['execution_plan']; file = (Path.cwd() / path).resolve()
    if not file.is_relative_to(Path.cwd()):
        raise ValueError('Execution plan outside repository')
    plan = json.loads(file.read_text())
    report = validate(plan, control['limits'], root=Path.cwd())
    source_check(plan, path, request)
    pipeline = json.loads(Path('analysis/CCC_BBN_NETWORK_20261114/pipeline/PIPELINE.json').read_text())
    if pipeline['branch'] != plan['publication_branch']:
        raise ValueError('Pipeline and execution-plan publication branches differ')
    if report['executor'] != 'github_actions':
        receipt({**report, 'execute': False, 'reason': 'HANDOFF_' + report['executor'].upper()})
        return
    # The existing CCC dispatcher runs a whole stage package. Do not repeat it
    # per section. Section-aware scientific adapters have their own workflows.
    if len(plan['sections']) != 1:
        raise ValueError('Use a package-specific section workflow; legacy dispatcher is single-section')
    if not control['enabled']:
        raise ValueError('Autonomous execution disabled')
    now = datetime.now(timezone.utc); run_id = int(os.environ['GITHUB_RUN_ID'])
    candidate = {'id': request['id'], 'executor': 'github_actions', 'started_utc': now.isoformat(),
                 'source_sha': plan['source_commit'], 'execution_plan_sha256': digest(plan),
                 'workflow_run_id': run_id, 'status': 'RESERVED', 'budget': plan['budget']}
    result = reserve(read_ledger, write_ledger, actions_runs(now), candidate, now, control['limits'], run_id)
    receipt({**report, **result, 'execute': result['admitted']})


if __name__ == '__main__':
    main()

"""Validate a frozen execution plan; do not submit jobs or accept science."""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path
import re

LOCAL_SECONDS = 600
GITHUB_JOB_SECONDS = 21600
SHA = re.compile(r"[0-9a-f]{40}")
DIGEST = re.compile(r"[0-9a-f]{64}")
IDENTIFIER = re.compile(r"[A-Za-z0-9_-]{1,100}")


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    allow_nan=False).encode()).hexdigest()


def number(value, name, *, zero=False):
    if (isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or value < 0 or (not zero and value == 0)):
        raise ValueError("Invalid budget: " + name)
    return value


def evidence(ref, root):
    path = ref.get("path", "")
    if not path or Path(path).is_absolute() or ".." in Path(path).parts or "\\" in path:
        raise ValueError("Unsafe evidence path")
    if not DIGEST.fullmatch(ref.get("sha256", "")):
        raise ValueError("Evidence requires SHA-256")
    if root is not None:
        root = Path(root).resolve()
        file = (root / path).resolve()
        if not file.is_relative_to(root) or not file.is_file():
            raise ValueError("Missing evidence: " + path)
        if hashlib.sha256(file.read_bytes()).hexdigest() != ref["sha256"]:
            raise ValueError("Changed evidence: " + path)


def validate(plan, limits, *, root=None):
    """Budgets are reservations, not forecasts; no historical limits are changed.

    A section executes whole tasks sequentially. Parallelism is between sections.
    A continuous calculation has exactly one task and one section, on one process.
    Package seconds are aggregate reserved executor time, including all sections.
    """
    if plan.get("schema") != "vm-lab-execution-plan-v1":
        raise ValueError("Unknown execution plan schema")
    if not IDENTIFIER.fullmatch(plan.get("package_id", "")):
        raise ValueError("Invalid package_id")
    if not SHA.fullmatch(plan.get("source_commit", "")):
        raise ValueError("Freeze a full source commit before execution")
    branch = plan.get("publication_branch", "")
    if not branch.startswith("science/autonomous-") or any(c in branch for c in " ~^:?*[\\"):
        raise ValueError("Invalid autonomous publication branch")
    if plan.get("scientific_acceptance") is not False or plan.get("automatic_retry") is not False:
        raise ValueError("Science acceptance/retry must remain disabled")
    kind = plan.get("workload_kind")
    if kind not in {"independent_realizations", "continuous"}:
        raise ValueError("Declare scientific divisibility")
    for key in ("input_manifest", "acceptance", "calibration"):
        evidence(plan[key], root)
    if not plan["calibration"].get("environment_reference"):
        raise ValueError("Calibration must identify the measured environment")
    number(plan["calibration"].get("measured_seconds"), "calibration.measured_seconds")
    if plan.get("checkpoint_policy") not in {"not_required", "method_defined"}:
        raise ValueError("Declare checkpoint semantics without assuming resumability")
    if plan["checkpoint_policy"] == "method_defined":
        evidence(plan["checkpoint_contract"], root)

    tasks = plan["tasks"]
    sections = plan["sections"]
    if not tasks or not sections:
        raise ValueError("Empty task/section matrix")
    ids = [task["id"] for task in tasks]
    section_ids = [section["id"] for section in sections]
    if any(not isinstance(i, str) or not IDENTIFIER.fullmatch(i) for i in ids + section_ids):
        raise ValueError("Invalid task/section identifier")
    if len(set(ids)) != len(ids) or len(set(section_ids)) != len(section_ids):
        raise ValueError("Duplicate task/section identifier")
    matrix = {task["id"]: task for task in tasks}
    for task in tasks:
        forecast = number(task["forecast_seconds"], "task.forecast_seconds")
        if number(task["process_seconds"], "task.process_seconds") < forecast:
            raise ValueError("Process cap below calibrated forecast")
        # Seeds may repeat intentionally across A/B pairs; task IDs may not.
        if "seed" in task and (type(task["seed"]) is not int or task["seed"] < 0):
            raise ValueError("Invalid preregistered seed")
    assignments = [i for section in sections for i in section["task_ids"]]
    if sorted(assignments) != sorted(ids):
        raise ValueError("Sections must cover every whole task exactly once")
    if kind == "continuous" and (len(tasks) != 1 or len(sections) != 1):
        raise ValueError("A continuous integration cannot be split into sections")

    b = plan["budget"]
    for key in ("package_seconds", "process_seconds", "section_seconds", "memory_bytes", "output_bytes"):
        number(b[key], key)
    if b["memory_bytes"] > limits["memory_bytes"] or b["output_bytes"] > limits["output_bytes"]:
        raise ValueError("Package exceeds authorized memory/output budget")
    parallelism = plan.get("parallel_sections", 1)
    if type(parallelism) is not int or not 1 <= parallelism <= len(sections):
        raise ValueError("Invalid section parallelism")
    if kind == "continuous" and parallelism != 1:
        raise ValueError("Continuous integration requires one process")
    peak_mem = []
    forecast_total = 0
    for section in sections:
        if not section["task_ids"]:
            raise ValueError("Empty section")
        compute = number(section["compute_seconds"], "section.compute_seconds")
        overhead = sum(number(section[key], key, zero=(key == "setup_seconds"))
                       for key in ("setup_seconds", "verification_seconds", "publication_seconds"))
        wall = number(section["wall_seconds"], "section.wall_seconds")
        if wall < compute + overhead:
            raise ValueError("Section must reserve preparation, verification and publication time")
        if compute < sum(matrix[i]["process_seconds"] for i in section["task_ids"]):
            raise ValueError("Section cannot finish its whole task matrix within compute budget")
        if wall > b["section_seconds"]:
            raise ValueError("Section exceeds declared section cap")
        mem = number(section["memory_bytes"], "section.memory_bytes")
        peak_mem.append(mem)
        forecast_total += overhead + sum(matrix[i]["forecast_seconds"] for i in section["task_ids"])
    if sum(sorted(peak_mem, reverse=True)[:parallelism]) > b["memory_bytes"]:
        raise ValueError("Concurrent sections exceed aggregate memory budget")
    if max(task["process_seconds"] for task in tasks) > b["process_seconds"]:
        raise ValueError("Task exceeds declared process cap")
    if sum(section["wall_seconds"] for section in sections) > b["package_seconds"]:
        raise ValueError("Package budget must cover every section, including overhead")

    if b["package_seconds"] <= LOCAL_SECONDS:
        route = "local"
    elif max(section["wall_seconds"] for section in sections) <= GITHUB_JOB_SECONDS:
        route = "github_actions"
    else:
        if kind == "independent_realizations":
            for section in sections:
                overhead = sum(section[k] for k in ("setup_seconds", "verification_seconds", "publication_seconds"))
                if (section["wall_seconds"] > GITHUB_JOB_SECONDS
                        and all(matrix[i]["process_seconds"] + overhead <= GITHUB_JOB_SECONDS
                                for i in section["task_ids"])):
                    raise ValueError("Repartition whole independent tasks; oversized batching is not a VM requirement")
        route = "vm"
    if plan.get("executor") != route or plan["calibration"].get("executor") != route:
        raise ValueError("Executor/calibration does not match the required route: " + route)
    if route == "vm":
        vm_seconds = number(b.get("vm_seconds"), "vm_seconds")
        if vm_seconds < b["package_seconds"]:
            raise ValueError("VM budget must cover the complete package")
        worker = plan["verified_vm_limits"]
        evidence(worker["evidence"], root)
        if (number(worker["wall_seconds"], "worker.wall_seconds") < vm_seconds
                or number(worker["memory_bytes"], "worker.memory_bytes") < b["memory_bytes"]
                or number(worker["output_bytes"], "worker.output_bytes") < b["output_bytes"]):
            raise ValueError("Verified VM worker limits do not support this package")
        if not worker.get("executor_id"):
            raise ValueError("Identify the verified VM worker")
    elif b.get("vm_seconds") is not None:
        raise ValueError("VM budget belongs only to the VM route")
    return {"package_id": plan["package_id"], "source_commit": plan["source_commit"],
            "plan_sha256": digest(plan), "executor": route,
            "forecast_seconds": forecast_total, "budget": b,
            "parallel_sections": parallelism,
            "sections": [{"id": s["id"], "task_ids": s["task_ids"],
                          "timeout_minutes": math.ceil(s["wall_seconds"] / 60)} for s in sections],
            "scientific_acceptance": False, "automatic_retry": False}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("plan", type=Path)
    ap.add_argument("--control", type=Path, default=Path("infra/autonomy/CONTROL.json"))
    ap.add_argument("--root", type=Path, default=Path.cwd())
    args = ap.parse_args()
    result = validate(json.loads(args.plan.read_text()), json.loads(args.control.read_text())["limits"], root=args.root)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

"""Close an Actions reservation after the scientific controller has exited."""
import json
import os
from pathlib import Path
import subprocess
from datetime import datetime, timezone
try:
    from .admit import read_ledger, write_ledger
except ImportError:
    from admit import read_ledger, write_ledger


def close(ledger, reservation, conclusion, publication_sha):
    if conclusion not in {'success', 'failure', 'cancelled'}:
        raise ValueError('Unknown terminal job conclusion')
    updated = json.loads(json.dumps(ledger))
    found = False
    for row in updated['packages']:
        if row['id'] != reservation['id']:
            continue
        found = True
        for key in ('source_sha', 'execution_plan_sha256', 'workflow_run_id'):
            if row.get(key) != reservation.get(key):
                raise ValueError('Reservation identity mismatch')
        if row['status'] not in {'RESERVED', 'RUNNING'}:
            raise ValueError('Reservation is already terminal; preserve first evidence')
        row.update(status='COMPLETED' if conclusion == 'success' else 'FAILED',
                   execution_conclusion=conclusion, publication_sha=publication_sha,
                   finished_utc=datetime.now(timezone.utc).isoformat(), scientific_acceptance=False)
    if not found:
        raise ValueError('Missing reservation')
    return updated


def main():
    path = Path(os.environ['RUNNER_TEMP'], 'autonomy-budget.json')
    if not path.exists():
        return
    admission = json.loads(path.read_text())
    if not admission.get('execute'):
        return
    reservation = admission['reservation']
    if reservation['workflow_run_id'] != int(os.environ['GITHUB_RUN_ID']):
        raise ValueError('Wrong workflow run')
    publication_sha = subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip()
    for _ in range(3):
        ledger, expected = read_ledger()
        updated = close(ledger, reservation, os.environ['EXECUTION_CONCLUSION'], publication_sha)
        if write_ledger(updated, expected):
            return
    raise ValueError('Cannot close reservation; preserve it until live status is reconciled')


if __name__ == '__main__':
    main()

